create extension if not exists pgcrypto;
create table if not exists public.users (id uuid primary key references auth.users(id) on delete cascade, email text, created_at timestamptz default now());
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), name text not null, color text not null, icon text not null, updated_at timestamptz default now());
create table if not exists public.activities (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), category_id uuid references categories(id), title text not null, description text, date date not null, start_time time not null, end_time time not null, location text, notes text, status text check (status in ('pendente','em andamento','concluída','cancelada')) default 'pendente', important boolean default false, project_id uuid, google_event_id text, updated_at timestamptz default now());
create table if not exists public.drafts (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), title text not null, description text, category_id uuid references categories(id), archived boolean default false, created_at timestamptz default now());
create table if not exists public.reading_logs (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), book text not null, author text, category text, start_page int, end_page int, date date, minutes int);
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), name text not null, type text, status text);
create table if not exists public.goals (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), area text not null, target numeric not null, unit text, period text);
create table if not exists public.alerts (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), activity_id uuid references activities(id), message text not null, read boolean default false, created_at timestamptz default now());
create table if not exists public.settings (user_id uuid primary key references auth.users(id), slot_minutes int default 30, theme text default 'light', auto_sync boolean default false);
create table if not exists public.calendar_sync (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), provider text default 'google', external_id text, direction text, last_synced_at timestamptz);
alter table categories enable row level security; alter table activities enable row level security; alter table drafts enable row level security; alter table reading_logs enable row level security; alter table projects enable row level security; alter table goals enable row level security; alter table alerts enable row level security; alter table settings enable row level security; alter table calendar_sync enable row level security;
create policy "owner all categories" on categories for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all activities" on activities for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all drafts" on drafts for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all readings" on reading_logs for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all projects" on projects for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all goals" on goals for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all alerts" on alerts for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all settings" on settings for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "owner all calendar_sync" on calendar_sync for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
